{"source":"#include <stdio.h>
#include <stdlib.h>

int a[100000];

int cmp(const void *a, const void *b)
{
    int x = *((int *)a);
    int y = *((int *)b);
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

void func(int n)
{
    int i;
    qsort(a, n, sizeof(int), cmp);
    for (i = 0; i < n - 1; i++)
    {
        if ((long long)a[i] * 2 > a[i + 1])
        {
            printf("YES\n");
            return;
        }
    }
    printf("NO\n");
}

int main(int argc, char **argv)
{
    int n, i;
    while (scanf("%d", &n) == 1)
    {
        for (i = 0; i < n; i++)
        {
            scanf("%d", &a[i]);
        }
        func(n);
    }
    return 0;
}"}
